// Extract patient and medication context from calling workflow
const inputData = $input.first().json;

const patientName = inputData.patientName || '';
const patientId = inputData.patientId || '';
const patientDOB = inputData.patientDOB || '';
const lastVisitDate = inputData.lastVisitDate || '';
const primaryDoctor = inputData.primaryDoctor || 'Dr. Jennifer';
const requestText = inputData.requestText || '';
const matchedMedication = inputData.matchedMedication || null;
const medications = inputData.medications || [];

// Find the specific medication requested
let requestedMed = null;
if (matchedMedication) {
  requestedMed = medications.find(m => 
    m.medicationName.toLowerCase() === matchedMedication.toLowerCase()
  );
}

// If no specific match, use the first medication (for ambiguous requests)
if (!requestedMed && medications.length > 0) {
  requestedMed = medications[0];
}

// Calculate days since last visit
let daysSinceLastVisit = null;
if (lastVisitDate) {
  const lastVisit = new Date(lastVisitDate);
  const now = new Date();
  daysSinceLastVisit = Math.floor((now - lastVisit) / (1000 * 60 * 60 * 24));
}

// Prepare structured context for AI
const aiContext = {
  patient: {
    name: patientName,
    id: patientId,
    dateOfBirth: patientDOB,
    lastVisitDate: lastVisitDate,
    daysSinceLastVisit: daysSinceLastVisit,
    primaryDoctor: primaryDoctor
  },
  request: {
    rawText: requestText,
    matchedMedication: matchedMedication
  },
  requestedMedication: requestedMed ? {
    name: requestedMed.medicationName,
    dosage: requestedMed.dosage,
    frequency: requestedMed.frequency,
    lastFilledDate: requestedMed.lastFilled,
    refillsRemaining: requestedMed.refillsRemaining || 0,
    isControlledSubstance: requestedMed.controlledSubstance === true,
    isActive: requestedMed.active === true
  } : null,
  allMedications: medications
};

return {
  json: aiContext
};

// Build comprehensive clinical prompt for Claude AI
const context = $input.first().json;

const patient = context.patient;
const request = context.request;
const medication = context.requestedMedication;
const allMeds = context.allMedications;

// Format medication list
const medList = allMeds.map((med, idx) => 
  `${idx + 1}. ${med.medicationName} ${med.dosage} - ${med.frequency} (Refills: ${med.refillsRemaining || 0}, Last filled: ${med.lastFilled || 'Unknown'})${med.controlledSubstance ? ' ⚠️ CONTROLLED' : ''}`
).join('\n');

// Build system prompt with clinical protocols
const systemPrompt = `You are a medical prescription refill triage assistant for Dr. Jennifer's practice.

Your role is to analyze refill requests and apply clinical protocols to determine the appropriate action.

CLINICAL PROTOCOLS:

✅ AUTO-APPROVE if ALL conditions met:
1. Medication is currently on file for this patient
2. At least 1 refill remaining on the prescription
3. Last visit was within 180 days (6 months)
4. NOT a controlled substance (Schedule II-V)
5. Request clearly matches an active medication

⚠️ NEEDS-APPROVAL if ANY condition met:
1. Last visit was 180-365 days ago (6 months to 1 year)
2. Zero refills remaining (needs new prescription)
3. Request is ambiguous or doesn't clearly match medication on file
4. Patient has multiple similar medications (e.g., different dosages)

🚨 ESCALATE IMMEDIATELY if ANY condition met:
1. Controlled substance (Schedule II-V: opioids, stimulants, benzodiazepines, etc.)
2. Last visit was over 365 days ago (>1 year)
3. Request mentions new medication not on file
4. Patient safety concern (e.g., mentions side effects, dosage confusion)
5. Request mentions changing dosage or frequency

RETURN FORMAT:
Respond with ONLY valid JSON (no markdown, no explanations outside JSON):
{
  "decision": "AUTO-APPROVE" | "NEEDS-APPROVAL" | "ESCALATE",
  "reasoning": "Brief clinical reasoning (1-2 sentences)",
  "confidence": 0.0-1.0,
  "flags": ["array of any concerns"],
  "recommendedAction": "What should happen next"
}`;

// Build user prompt with patient context
const userPrompt = `PATIENT CONTEXT:
Name: ${patient.name}
ID: ${patient.id}
Last Visit: ${patient.lastVisitDate || 'Unknown'} ${patient.daysSinceLastVisit !== null ? `(${patient.daysSinceLastVisit} days ago)` : ''}
Primary Doctor: ${patient.primaryDoctor}

PATIENT'S CURRENT MEDICATIONS:
${medList}

REFILL REQUEST:
Patient sent: "${request.rawText}"
${request.matchedMedication ? `Matched medication: ${request.matchedMedication}` : 'No clear medication match'}

${medication ? `REQUESTED MEDICATION DETAILS:
- Name: ${medication.name}
- Dosage: ${medication.dosage}
- Frequency: ${medication.frequency}
- Last Filled: ${medication.lastFilledDate || 'Unknown'}
- Refills Remaining: ${medication.refillsRemaining}
- Controlled Substance: ${medication.isControlledSubstance ? 'YES ⚠️' : 'No'}
- Status: ${medication.isActive ? 'Active' : 'Inactive'}` : 'No medication matched - patient may be requesting new medication'}

QUESTION: Based on the clinical protocols, should this refill request be AUTO-APPROVED, require doctor approval (NEEDS-APPROVAL), or be ESCALATED immediately?`;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    // Pass through context for later nodes
    patientContext: context
  }
};

// Parse Claude's JSON response and validate
const aiResponse = $input.first().json;
const promptData = $('Build Clinical Prompt').first().json;

let decision = null;
let parseError = false;

// Try to extract JSON from AI response
try {
  // Claude might return markdown-wrapped JSON, so extract it
  let responseText = '';

  // Handle different response formats from LangChain node
  if (typeof aiResponse === 'string') {
    responseText = aiResponse;
  } else if (aiResponse.response) {
    responseText = aiResponse.response;
  } else if (aiResponse.text) {
    responseText = aiResponse.text;
  } else if (aiResponse.output) {
    responseText = aiResponse.output;
  } else {
    // If response is already an object with decision field
    if (aiResponse.decision) {
      decision = aiResponse;
    } else {
      responseText = JSON.stringify(aiResponse);
    }
  }

  if (!decision && responseText) {
    // Remove markdown code blocks if present
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Parse JSON
    decision = JSON.parse(responseText);
  }

  // Validate decision structure
  if (!decision.decision || !['AUTO-APPROVE', 'NEEDS-APPROVAL', 'ESCALATE'].includes(decision.decision)) {
    throw new Error('Invalid decision value');
  }

} catch (error) {
  console.error('Failed to parse AI response:', error.message);
  parseError = true;

  // Fallback: escalate on parse errors (safety first)
  decision = {
    decision: 'ESCALATE',
    reasoning: `AI response parsing failed: ${error.message}. Escalating for manual review.`,
    confidence: 0.0,
    flags: ['parse-error', 'manual-review-required'],
    recommendedAction: 'Manual review by doctor required due to system error'
  };
}

// Add metadata
const output = {
  // AI decision
  decision: decision.decision,
  reasoning: decision.reasoning || 'No reasoning provided',
  confidence: decision.confidence || 0.0,
  flags: decision.flags || [],
  recommendedAction: decision.recommendedAction || '',

  // Metadata
  parseError: parseError,
  timestamp: new Date().toISOString(),
  aiModel: 'claude-3-5-sonnet-20241022',

  // Original context (for next workflow)
  patientContext: promptData.patientContext,

  // For audit log
  systemPrompt: promptData.systemPrompt,
  userPrompt: promptData.userPrompt,
  rawAIResponse: aiResponse
};

return { json: output };
